<?php
define('NOLOGIN', 1);
define('NOREQUIREMENU', 1);
define('NOREQUIREHTML', 1);
define('NOCSRFCHECK', 1);
$_SERVER['DOCUMENT_ROOT'] = '/Users/mac/Documents/dev/dolibarr/dolibarr-Dev/dolibarr-23.0.3/htdocs';
$_SERVER['SERVER_NAME'] = '127.0.0.1';
$_SERVER['SERVER_PORT'] = '8088';
require $_SERVER['DOCUMENT_ROOT'].'/master.inc.php';
require_once DOL_DOCUMENT_ROOT.'/custom/chinaplanetshippingprices/class/ShippingPriceService.class.php';

function spAssert($condition, $message) { if (!$condition) throw new RuntimeException($message); }
$blockSchema = file_get_contents(DOL_DOCUMENT_ROOT.'/custom/chinaplanetshippingprices/sql/llx_chinaplanetsp_block.sql');
$blockSchema = str_replace(array('CREATE TABLE llx_', 'llx_chinaplanetsp_'), array('CREATE TABLE IF NOT EXISTS '.MAIN_DB_PREFIX, MAIN_DB_PREFIX.'chinaplanetsp_'), $blockSchema);
spAssert($db->query($blockSchema), 'Could not install disabled-price scope table: '.$db->lasterror());
$res = $db->query("SELECT COUNT(*) total,MIN(cost_price) minimum,SUM(is_current=1) current_total,SUM(status=1) published_total FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".(int)$conf->entity);
$stats = $res ? $db->fetch_object($res) : null;
spAssert($stats && (int)$stats->total > 100, 'Expected imported rates.');
spAssert((float)$stats->minimum >= 1000, 'Ignore threshold was not enforced.');
spAssert((int)$stats->current_total > 100 && (int)$stats->current_total <= (int)$stats->published_total, 'Published current rate flags are inconsistent.');
$service = new ShippingPriceService($db);
$filterOptions = $service->getFilterOptions(true);
spAssert(isset($filterOptions['countries']['EG']) && strtoupper($filterOptions['countries']['EG']) === 'EGYPT', 'Country code EG was not resolved to Egypt.');
spAssert(isset($filterOptions['pod_by_country']['EG']['SOKHNA']), 'Egypt POD list does not contain SOKHNA.');
spAssert(!isset($filterOptions['pod_by_country']['EG']['ABU DHABI']), 'Egypt POD list contains a UAE port.');
$public = $service->search(array('pod'=>'SOKHNA','container_type'=>'20GP','incoterm'=>'FOB','cargo_type'=>'normal'), false);
spAssert(count($public['results']) > 0, 'SOKHNA public search returned no result.');
spAssert(!array_key_exists('supplier_cost', $public['results'][0]), 'Public service leaked supplier cost.');
foreach($public['results'] as $result)spAssert($result['pol']!=='UNKNOWN'&&$result['shipping_line']!=='UNKNOWN'&&!empty($result['country_code']),'Public service exposed an unmapped rate.');
$projectionRate = $public['results'][0];
$db->begin();
$projectionUpdate = "UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rate SET source_notes='M041 synthetic private source',notes_en='M041 synthetic private English',translation_status='failed',public_notes='M041_MUST_NOT_LEAK' WHERE entity=".(int)$conf->entity." AND rowid=".(int)$projectionRate['rate_id'];
spAssert($db->query($projectionUpdate), 'Could not prepare failed-translation projection test.');
$projectionSearch = $service->search(array('pol'=>$projectionRate['pol'],'country_code'=>$projectionRate['country_code'],'pod'=>$projectionRate['pod'],'shipping_line'=>$projectionRate['shipping_line'],'container_type'=>$projectionRate['container_type'],'service_type'=>$projectionRate['service_type'],'incoterm'=>'FOB','cargo_type'=>'normal'), false, 250);
$projectionFound = null; foreach ($projectionSearch['results'] as $candidate) if ((int)$candidate['rate_id'] === (int)$projectionRate['rate_id']) $projectionFound = $candidate;
spAssert($projectionFound !== null && $projectionFound['notes'] === '' && strpos(json_encode($projectionFound), 'M041_MUST_NOT_LEAK') === false, 'Failed M041 translation leaked through public DTO.');
spAssert($db->query("UPDATE ".MAIN_DB_PREFIX."chinaplanetsp_rate SET translation_status='approved',public_notes='M041 approved English note' WHERE entity=".(int)$conf->entity." AND rowid=".(int)$projectionRate['rate_id']), 'Could not prepare approved-translation projection test.');
$approvedSearch = $service->search(array('pol'=>$projectionRate['pol'],'country_code'=>$projectionRate['country_code'],'pod'=>$projectionRate['pod'],'shipping_line'=>$projectionRate['shipping_line'],'container_type'=>$projectionRate['container_type'],'service_type'=>$projectionRate['service_type'],'incoterm'=>'FOB','cargo_type'=>'normal'), false, 250);
$approvedFound = null; foreach ($approvedSearch['results'] as $candidate) if ((int)$candidate['rate_id'] === (int)$projectionRate['rate_id']) $approvedFound = $candidate;
spAssert($approvedFound !== null && $approvedFound['notes'] === 'M041 approved English note', 'Approved M041 translation missing from public DTO.');
$db->rollback();
$historyBeforeBlock=$service->history($public['results'][0],18,true);
$db->begin();
$blockSql="INSERT INTO ".MAIN_DB_PREFIX."chinaplanetsp_block SET entity=".(int)$conf->entity.",label='TEST temporary country stop',country_code='EG',pod='SOKHNA',container_type='20GP',status=1,fk_user_creat=1,date_creation='".$db->idate(dol_now())."'";
spAssert($db->query($blockSql),'Could not prepare disabled-price test.');
$blocked=$service->search(array('country_code'=>'EG','pod'=>'SOKHNA','container_type'=>'20GP','incoterm'=>'FOB','cargo_type'=>'normal'),false);
spAssert(count($blocked['results'])===0,'Disabled scope still appeared in live inquiry.');
$historyWhileBlocked=$service->history($public['results'][0],18,true);
spAssert(count($historyWhileBlocked)===count($historyBeforeBlock),'Disabled scope was incorrectly removed from history.');
$db->rollback();
$internal = $service->search(array('pod'=>'SOKHNA','container_type'=>'20GP','incoterm'=>'FOB','cargo_type'=>'normal'), true);
spAssert(array_key_exists('supplier_cost', $internal['results'][0]), 'Internal service did not return supplier cost.');
spAssert(abs(($internal['results'][0]['base_sale_price']-$internal['results'][0]['supplier_cost'])-200) < 0.01, '20GP base margin is incorrect.');
$db->begin();
$overrideSql="INSERT INTO ".MAIN_DB_PREFIX."chinaplanetsp_rule SET entity=".(int)$conf->entity.",label='TEST exact price',public_label='Manual adjustment',component_type='adjustment',pod='SOKHNA',container_type='20GP',calc_type='override',amount=9999,currency_code='USD',priority=500,stackable=0,status=1,fk_user_creat=1,date_creation='".$db->idate(dol_now())."'";
spAssert($db->query($overrideSql), 'Could not prepare exact-price adjustment test.');
$overridden=$service->search(array('pod'=>'SOKHNA','container_type'=>'20GP','incoterm'=>'FOB','cargo_type'=>'normal'),true);
spAssert(!empty($overridden['results'])&&abs($overridden['results'][0]['final_price']-9999)<0.01,'Exact-price adjustment was not applied as the final price.');
$db->rollback();
$exw = $service->search(array('pod'=>'SOKHNA','container_type'=>'20GP','incoterm'=>'EXW','cargo_type'=>'normal'), false);
spAssert(!empty($exw['results'][0]['needs_manual_review']), 'EXW without origin rule must require manual review.');
$history = $service->history($public['results'][0], 18, true);
if(count($history)<5)$history=$service->marketHistory($public['results'][0],18,true);
if(count($history)<5)$history=$service->comparisonHistory(array('country_code'=>'EG','pod'=>'SOKHNA'),18,true);
spAssert(count($history) >= 5, 'Historical backfill did not produce enough comparable points.');
$comparison = $service->comparisonHistory(array('pol'=>'Guangzhou','country_code'=>'EG','pod'=>'SOKHNA','service_type'=>'direct'), 18, true);
spAssert(count($comparison) >= 5, 'Comparison history did not produce enough points.');
$comparisonLines = array_unique(array_column($comparison, 'line'));
spAssert(count($comparisonLines) >= 2, 'Comparison history did not separate shipping lines.');
foreach($comparison as $point) spAssert(!empty($point['line']) && (float)$point['sale_price'] >= 1000, 'Comparison history contains an invalid line or sub-threshold price.');
$rightsRes = $db->query("SELECT SUM(fk_soc IS NULL OR fk_soc=0) internal_users,SUM(fk_soc>0) external_users FROM ".MAIN_DB_PREFIX."user WHERE statut=1");
$users = $rightsRes ? $db->fetch_object($rightsRes) : null;
$readRes = $db->query("SELECT SUM(u.fk_soc IS NULL OR u.fk_soc=0) internal_with_read,SUM(u.fk_soc>0) external_with_read FROM ".MAIN_DB_PREFIX."user u INNER JOIN ".MAIN_DB_PREFIX."user_rights ur ON ur.fk_user=u.rowid AND ur.fk_id=500401 AND ur.entity=".(int)$conf->entity." WHERE u.statut=1");
$readUsers = $readRes ? $db->fetch_object($readRes) : null;
print 'OK rates='.(int)$stats->total.' minimum='.(float)$stats->minimum.' sokhna_results='.count($public['results']).' block_scope=passed history_points='.count($history).' comparison_lines='.count($comparisonLines).' internal_users='.(int)$users->internal_users.' external_users='.(int)$users->external_users.' internal_read='.(int)($readUsers->internal_with_read??0).' external_read='.(int)($readUsers->external_with_read??0)."\n";
